input.command:
echo "=== OPEN PRs ===" && gh pr list --state open --limit 20 --json number,title,headRefName,isDraft,reviewDecision,mergeable --template '{{range .}}#{{.number}}  {{.headRefName}}  [{{.reviewDecision}}/{{.mergeable}}]{{if .isDraft}} DRAFT{{end}}
   {{.title}}
{{end}}' 2>&1 | head -50

echo "=== PR #68 FULL ===" && gh pr view 68 --json number,title,headRefName,baseRefName,author,body,createdAt,updatedAt,additions,deletions,changedFiles --template '#{{.number}} {{.title}}
branch: {{.headRefName}} → {{.baseRefName}}
author: {{.author.login}}
created: {{.createdAt}}  updated: {{.updatedAt}}
diff: +{{.additions}}/-{{.deletions}} across {{.changedFiles}} files

--- BODY ---
{{.body}}'

