import { describe, test, expect } from 'vitest';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import { selectPdpProductInfo } from './productInfo';

// Realistic broken-size-run markdown: one colourway, 6 sizes, all list $795,
// only size 6 marked down to $595 in the sale price book.
const v = (size: string, price: number, tiers: number[]) => ({
  productId: `M-JJ8UTXX-${size}`,
  variationValues: { color: 'JJ8UTXX', size },
  price,
  tieredPrices: tiers.map((p) => ({ price: p, quantity: 1 })),
});

const colourVariants = [
  v('0', 795, [795]), v('2', 795, [795]), v('4', 795, [795]),
  v('6', 595, [595, 795]),                                    // <- the only markdown
  v('8', 795, [795]), v('10', 795, [795]),
];
const master = { id: 'M', name: 'INDRA PLUNGE HALTER MAXI DRESS', type: { master: true }, variants: colourVariants };
const fmt = (a: number) => `$${a.toLocaleString('en-AU', { minimumFractionDigits: 2 })}`;

describe('Blocker 2 — isRange discarded', () => {
  test('colour-only selection renders a definite Was/Now for a price RANGE', () => {
    const priceData = getPriceData(master, { quantity: 1 });
    console.log('  colour-only priceData =', JSON.stringify({
      currentPrice: priceData.currentPrice, listPrice: priceData.listPrice,
      isOnSale: priceData.isOnSale, isRange: priceData.isRange }));

    expect(priceData.isRange).toBe(true);            // SFCC says: this is a range
    const info = selectPdpProductInfo(master, priceData, 'AUD', fmt);
    console.log('  rendered =>', `"Was ${info!.wasPrice} Now ${info!.price}"`);

    // The mapper emits a definite Was/Now anyway, discarding isRange:
    expect(info!.price).toBe('$595.00');
    expect(info!.wasPrice).toBe('$795.00');
  });

  test('then picking size 10 silently drops the sale treatment', () => {
    const size10 = { ...colourVariants[5], id: 'M-JJ8UTXX-10', name: 'INDRA PLUNGE HALTER MAXI DRESS', type: { variant: true }, master: { masterId: 'M' } };
    const priceData = getPriceData(size10, { quantity: 1 });
    const info = selectPdpProductInfo(size10, priceData, 'AUD', fmt);
    console.log('  size 10 =>', `price=${info!.price} wasPrice=${String(info!.wasPrice)}`);
    expect(info!.price).toBe('$795.00');
    expect(info!.wasPrice).toBeUndefined();          // sale treatment gone
  });
});
